fn main() { let group=std::fs::read_to_string("/proc/self/cgroup").unwrap(); let rel=group.lines().find_map(|s|s.strip_prefix("0::")).unwrap().trim_start_matches('/'); let cg=std::path::Path::new("/sys/fs/cgroup").join(rel); let report=format!("{}memory.max={}memory.high={}",group,std::fs::read_to_string(cg.join("memory.max")).unwrap(),std::fs::read_to_string(cg.join("memory.high")).unwrap()); std::fs::write(std::env::var("PROBE_RECEIPT").unwrap(), &report).unwrap(); assert!(group.contains(&std::env::var("EXPECTED_SCOPE").unwrap()), "compiler child outside selected memory cgroup: {}", report); }
